import type { MenuSound } from "./menu-sound.ts";

export interface MenuFeedbackOptions {
  document: Document;
  root: () => HTMLElement | null;
  snapshot: () => unknown;
  play: (kind: MenuSound) => void;
}

// One semantic cue per action, including clicks generated by keyboard/gamepad.
export class MenuFeedback {
  declare snapshot: () => unknown;
  declare play: (kind: MenuSound) => void;
  declare depth: number;
  constructor({ document, root, snapshot, play }: MenuFeedbackOptions) {
    this.snapshot = snapshot;
    this.play = play;
    this.depth = 0;
    const values = new WeakMap<HTMLInputElement, string>();
    for (const input of document.querySelectorAll("input"))
      values.set(input, input.value);
    document.addEventListener("input", (event) => {
      const input = event.target as HTMLInputElement;
      if (!root()?.contains(input)) return;
      const previous = values.get(input);
      values.set(input, input.value);
      if (!this.depth && previous !== input.value) play("move");
    });
    document.addEventListener("change", (event) => {
      if (
        !this.depth &&
        (event.target as Element).matches('input[type="radio"]') &&
        root()?.contains(event.target as Node)
      )
        play("move");
    });
    document.addEventListener(
      "click",
      (event) => {
        const panel = root();
        if (this.depth || !panel?.contains(event.target as Node)) return;
        const item = (event.target as Element).closest<
          HTMLButtonElement | HTMLInputElement
        >("button, input, label");
        // Labels produce a second click on their input; handle that click only.
        if (
          !item ||
          item.matches('label, input[type="radio"], input[type="range"]') ||
          item.disabled
        )
          return;
        const before = snapshot();
        const selection = item.matches(
          '#tracks .choice, #crafts .choice, input[type="radio"]',
        );
        const kind = item.matches("#setup-back, #resume, .close")
          ? "back"
          : selection
            ? "move"
            : "confirm";
        // Run after the target handler, but still inside the trusted gesture.
        const finish = () => {
          document.removeEventListener("click", finish);
          if (!selection || snapshot() !== before) play(kind);
        };
        document.addEventListener("click", finish, { once: true });
      },
      true,
    );
  }

  run<T>(kind: MenuSound, action: () => T): T {
    if (this.depth) return action();
    const before = this.snapshot();
    this.depth++;
    try {
      return action();
    } finally {
      this.depth--;
      if (kind === "confirm" || this.snapshot() !== before) this.play(kind);
    }
  }
}
